/**
 * ADD this one file beside HardwareShopApp.kt:
 * app/src/main/java/com/hardwareshop/pos/ShopItemCatalog.kt
 *
 * In HardwareShopApp.onCreate(), AFTER super.onCreate(), add this ONE line:
 *     ShopItemCatalog.install(this)
 *
 * Rebuild and install the APK as an UPDATE, then open Owner > Pending Item Details.
 * There is no database migration, Firebase change, or uninstall needed.
 *
 * All 1527 catalogue rows are imported as editable drafts with category/type,
 * product name, size and unit filled wherever identifiable.
 * Supplied buying and selected selling prices ARE populated. Pack capacities
 * (e.g. 1 L paint tin) are sizes; Piece means the price is for one whole container.
 * Per-metre/foot/kg/box/case rates keep their original price basis.
 * Highest clear same-basis selling prices are selected; uncertain handwritten rates remain blank.
 * referenceNotes retain price history, unit bases and unresolved details.
 * No additional GST is calculated; quoted buying totals are used as supplied.
 * Missing stock, GST, minimum stock and unknown prices remain blank for review.
 * Unclear identities remain under Other > Needs Identification.
 *
 * Older pending drafts receive these details once, preserving manual edits.
 * Buying prices, higher manual selling prices, units, names and sizes are preserved.
 * A newly supplied higher selling price updates pending drafts once on the same unit basis.
 * Completed/discarded rows are not recreated; existing saleable products are untouched.
 * Pending drafts and their import markers are included in the app's backups.
 * To extend this list later, add Item(...) rows with distinct complete names.
 */
object ShopItemCatalog {
    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.IO)
    private val installing = AtomicBoolean(false)

    fun install(context: Context) {
        if (!installing.compareAndSet(false, true)) return
        val appContext = context.applicationContext
        scope.launch {
            try {
                val entries = items()
                validate(entries)
                val db = AppDatabase.getInstance(appContext)
                // Let the app finish its own fresh-install category seeding first.
                // Waiting outside the transaction avoids blocking that seed transaction.
                withTimeout(30_000L) {
                    db.categoryDao().observeAllCategories().first { it.isNotEmpty() }
                }
                val added = db.withTransaction {
                    val groups = GroupResolver(db.categoryDao(), db.productTypeDao())
                    mergeDrafts(db.settingsDao(), entries, System.currentTimeMillis(), groups::resolve)
                }
                Timber.i("Master item catalogue: %d pending drafts added", added)
            } catch (e: CancellationException) {
                throw e
            } catch (e: Exception) {
                // Room rolls back the entire batch; the next launch can retry.
                Timber.e(e, "Could not add master item drafts")
            } finally {
                installing.set(false)
            }
        }
    }

    internal data class Item(
        val name: String,
        val buying: String,
        val referenceSelling: String,
        val stock: String,
        val group: Group,
        val lookupAliases: String = "",
        val referenceNotes: String = "",
        val previousBuying: String = "",
        val needsReview: Boolean = false,
        val productName: String? = null,
        val size: String? = null,
        val unit: String? = null,
        val selling: String? = null
    ) {
        val legacyDisplayName: String get() = (when (group) {
            Group.COLOUR_PAINT -> "Paint – $name"
            Group.PAINT_COLOUR -> "Paint Colour – $name"
            else -> name
        }) + if (needsReview) " (review details)" else ""
        val displayName: String get() = productName?.let {
            it + if (needsReview) " (review details)" else ""
        } ?: legacyDisplayName
        val searchTerms: String get() = listOf(name, group.category, group.type, lookupAliases).filter { it.isNotBlank() }.joinToString(", ")
        val id: String get() = "master-item-" + UUID.nameUUIDFromBytes(
            ("hardware-shop-master:" + name.trim().lowercase(Locale.ROOT))
                .toByteArray(Charsets.UTF_8)
        )
    }

    internal fun validate(entries: List<Item>) {
        require(entries.map { it.id }.distinct().size == entries.size) {
            "Duplicate names in the master item catalogue"
        }
        entries.forEach { item ->
            require(item.name.isNotBlank())
            (listOf(item.buying, item.previousBuying, item.stock, item.selling.orEmpty()) + item.referenceSelling.split("|").map { it.trim() }).forEach { value ->
                require(value.isBlank() || ProductForm.scaled(value) != null) {
                    "Invalid number for ${item.name}"
                }
            }
        }
    }

