    internal data class GroupIds(val categoryId: Long, val typeId: Long)

    // Resolve real database IDs by name; IDs differ between phones and backups.
    // Caller holds a transaction, serialising imports and category creation.
    internal class GroupResolver(
        private val categories: CategoryDao,
        private val types: ProductTypeDao
    ) {
        private val resolved = mutableMapOf<Group, GroupIds>()

        suspend fun resolve(group: Group): GroupIds {
            resolved[group]?.let { return it }
            val allCategories = categories.getAllCategories()
            val categoryName = availableName(group.category, allCategories.map { it.name to it.isActive })
            val categoryId = allCategories.firstOrNull {
                sameName(it.name, categoryName) && it.isActive
            }?.id ?: categories.insertCategory(CategoryEntity(
                name = categoryName,
                displayOrder = (allCategories.maxOfOrNull { it.displayOrder } ?: -1) + 1
            ))
            val allTypes = types.getTypesForCategory(categoryId)
            val typeName = availableName(group.type, allTypes.map { it.name to it.isActive })
            val typeId = allTypes.firstOrNull {
                sameName(it.name, typeName) && it.isActive
            }?.id ?: types.insertType(ProductTypeEntity(
                categoryId = categoryId, name = typeName,
                displayOrder = (allTypes.maxOfOrNull { it.displayOrder } ?: -1) + 1
            ))
            return GroupIds(categoryId, typeId).also { resolved[group] = it }
        }

        private fun sameName(a: String, b: String) = a.trim().equals(b.trim(), ignoreCase = true)

        // Do not reactivate categories/types that the owner deliberately disabled.
        private fun availableName(base: String, rows: List<Pair<String, Boolean>>): String {
            var candidate = base
            var suffix = 1
            while (true) {
                val matches = rows.filter { sameName(it.first, candidate) }
                if (matches.isEmpty() || matches.any { it.second }) return candidate
                candidate = if (suffix == 1) "$base (Catalog)" else "$base (Catalog $suffix)"
                suffix++
            }
        }
    }

    // Drafts, categories, types and import markers commit in one Room transaction.
    internal suspend fun mergeDrafts(
        settings: SettingsDao,
        entries: List<Item>,
        now: Long,
        resolve: suspend (Group) -> GroupIds
    ): Int {
        validate(entries)
        val gson = Gson()
        var added = 0
        entries.forEach { item ->
            val id = item.id
            val marker = "product:catalog:$id"
            val draftKey = "product:draft:$id"
            val dataKey = "product:catalog-data:$id"
            val priorData = settings.getSetting(dataKey)
            val priorItem = priorData?.let {
                runCatching { gson.fromJson(it.value, Item::class.java) }.getOrNull()
            }
            val previous = settings.getSetting(draftKey)
            val imported = settings.getSetting(marker) != null
            val done = settings.getSetting("product:done:$id") != null
            if (!done && previous == null && !imported) {
                val group = resolve(item.group)
                val draft = ProductDraft(
                    id = id,
                    form = ProductForm(
                        categoryId = group.categoryId, typeId = group.typeId,
                        name = item.displayName, aliases = item.searchTerms,
                        size = item.size.orEmpty(), unit = item.unit.orEmpty(),
                        sellingPrice = item.selling.orEmpty(), purchasePrice = item.buying,
                        gstPercent = "", stock = item.stock, minimumStock = ""
                    ),
                    updatedAt = now
                )
                settings.upsertSetting(SettingsEntity(draftKey, gson.toJson(draft), now))
                added++
            } else if (!done && previous != null) {
                // Upgrade the earlier file's drafts, preserving prices, names edited
                // by the owner, stock and all other details. Leave unreadable data alone.
                val draft = runCatching { gson.fromJson(previous.value, ProductDraft::class.java) }.getOrNull()
                val oldForm = draft?.form
                if (draft?.id == id && draft.productId == null && oldForm != null) {
                    var form = oldForm
                    if (form.categoryId == 0L && form.typeId == 0L) {
                        val group = resolve(item.group)
                        form = form.copy(
                            categoryId = group.categoryId, typeId = group.typeId,
                            name = if (form.name == item.name) item.displayName else form.name,
                            aliases = form.aliases.ifBlank { item.searchTerms }
                        )
                    }
                    val previousName = priorItem?.displayName ?: item.legacyDisplayName
                    if (priorItem?.productName != item.productName &&
                        (form.name == previousName || form.name == item.name)) {
                        form = form.copy(name = item.displayName)
                    }
                    if (priorItem?.size != item.size && !item.size.isNullOrBlank() &&
                        (form.size.isBlank() || form.size == priorItem?.size)) {
                        form = form.copy(size = item.size.orEmpty())
                    }
                    // Never change a selected unit automatically: that would change
                    // the meaning of the owner's existing stock and price amounts.
                    if (priorItem?.unit != item.unit && form.unit.isBlank() && !item.unit.isNullOrBlank()) {
                        form = form.copy(unit = item.unit.orEmpty())
                    }
                    val matchingBasis = form.unit == item.unit.orEmpty()
                    // Buying prices in existing drafts are never changed by this import.
                    // Raise selling only for a new catalogue price, and only on the
                    // same unit basis. Preserve higher manual prices and later edits.
                    val newSelling = item.selling.orEmpty()
                    val newAmount = ProductForm.scaled(newSelling)
                    val currentAmount = ProductForm.scaled(form.sellingPrice)
                    if (matchingBasis && priorItem?.selling != item.selling && newAmount != null &&
                        (form.sellingPrice.isBlank() || (currentAmount != null && newAmount > currentAmount))) {
                        form = form.copy(sellingPrice = newSelling)
                    }
                    if (priorItem?.lookupAliases != item.lookupAliases &&
                        (form.aliases.isBlank() || form.aliases == priorItem?.searchTerms)) {
                        form = form.copy(aliases = item.searchTerms)
                    }
                    if (form != oldForm) settings.upsertSetting(SettingsEntity(
                        draftKey, gson.toJson(draft.copy(form = form, updatedAt = now)), now
                    ))
                }
            }
            // Keep exact price bases, uncertainty and earlier references in backups.
            // Completed/discarded products are not recreated or edited.
            val metadata = gson.toJson(item)
            if (priorData?.value != metadata) {
                settings.upsertSetting(SettingsEntity(dataKey, metadata, now))
            }
            if (!imported) settings.upsertSetting(SettingsEntity(marker, "imported", now))
        }
        return added
    }

